     1→import {digest} from "@chainsafe/as-sha256";
     2→import {DOMAIN_VOLUNTARY_EXIT, ForkName, ForkSeq, SLOTS_PER_EPOCH} from "@lodestar/params";
     3→import {DomainType, Epoch, ForkDigest, Root, Slot, Version, phase0, ssz} from "@lodestar/types";
     4→import {intToBytes, strip0xPrefix, toHex, xor} from "@lodestar/utils";
     5→import {ChainForkConfig} from "../beaconConfig.js";
     6→import {ForkBoundary} from "../forkConfig/types.js";
     7→import {CachedGenesis, ForkDigestHex} from "./types.js";
     8→export type {ForkDigestContext} from "./types.js";
     9→
    10→export function createCachedGenesis(chainForkConfig: ChainForkConfig, genesisValidatorsRoot: Root): CachedGenesis {
    11→  const domainCache = new Map<ForkName, Map<DomainType, Uint8Array>>();
    12→
    13→  const forkDigestByEpoch = new Map<Epoch, ForkDigest>();
    14→  const forkDigestHexByEpoch = new Map<Epoch, ForkDigestHex>();
    15→  /** Map of ForkDigest in hex format without prefix: `0011aabb` */
    16→  const epochByForkDigest = new Map<ForkDigestHex, Epoch>();
    17→
    18→  const {forkBoundariesAscendingEpochOrder} = chainForkConfig;
    19→
    20→  for (let i = 0; i < forkBoundariesAscendingEpochOrder.length; i++) {
    21→    const currentForkBoundary = forkBoundariesAscendingEpochOrder[i];
    22→    const nextForkBoundary = forkBoundariesAscendingEpochOrder[i + 1];
    23→
    24→    const currentEpoch = currentForkBoundary.epoch;
    25→    const nextEpoch = nextForkBoundary !== undefined ? nextForkBoundary.epoch : Infinity;
    26→
    27→    // Edge case: If multiple fork boundaries start at the same epoch, only consider the latest one
    28→    if (currentEpoch === nextEpoch) {
    29→      continue;
    30→    }
    31→
    32→    const forkDigest = computeForkDigest(chainForkConfig, genesisValidatorsRoot, currentEpoch);
    33→    const forkDigestHex = toHexStringNoPrefix(forkDigest);
    34→
    35→    epochByForkDigest.set(forkDigestHex, currentEpoch);
    36→    forkDigestByEpoch.set(currentEpoch, forkDigest);
    37→    forkDigestHexByEpoch.set(currentEpoch, forkDigestHex);
    38→  }
    39→
    40→  return {
    41→    genesisValidatorsRoot,
    42→
    43→    getDomain(stateSlot: Slot, domainType: DomainType, messageSlot?: Slot): Uint8Array {
    44→      // ```py
    45→      // def get_domain(state: BeaconState, domain_type: DomainType, epoch: Epoch=None) -> Domain:
    46→      //   """
    47→      //   Return the signature domain (fork version concatenated with domain type) of a message.
    48→      //   """
    49→      //   epoch = get_current_epoch(state) if epoch is None else epoch
    50→      //   fork_version = state.fork.previous_version if epoch < state.fork.epoch else state.fork.current_version
    51→      //   return compute_domain(domain_type, fork_version, state.genesis_validators_root)
    52→      // ```
    53→
    54→      const epoch = Math.floor((messageSlot ?? stateSlot) / SLOTS_PER_EPOCH);
    55→      // Get pre-computed fork schedule, which _should_ match the one in the state
