    29→export function computeProposers(
    30→  fork: ForkSeq,
    31→  epochSeed: Uint8Array,
    32→  shuffling: {epoch: Epoch; activeIndices: Uint32Array},
    33→  effectiveBalanceIncrements: EffectiveBalanceIncrements
    34→): number[] {
