    42→        shuffling.activeIndices,
    43→        // TODO: if we use hashTree, we can precompute the roots for the next n loops
    44→        digest(Buffer.concat([epochSeed, intToBytes(slot, 8)]))
    45→      )
    46→    );
    47→  }
