   324→      // optimized version of the below naive code
   325→      // const pivot = Number(
   326→      //   bytesToBigInt(digest(Buffer.concat([_seed, intToBytes(i, 1)])).slice(0, 8)) % BigInt(indexCount)
   327→      // );
   328→
   329→      let pivot = pivotByIndex.get(i);
   330→      if (pivot == null) {
   331→        // naive version always creates a new buffer, we can reuse the buffer
   332→        // pivot = Number(
   333→        //   bytesToBigInt(digest(Buffer.concat([_seed, intToBytes(i, 1)])).slice(0, 8)) % BigInt(indexCount)
   334→        // );
   335→        pivotBuffer[32] = i % 256;
